<script setup lang="ts">import { computed } from "vue"; import { SISTEMA_NOMBRE_MAX,type CatalogoSistemaFieldErrors,type CatalogoSistemaGuardarInput } from "@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.types"; const props=defineProps<{draft:CatalogoSistemaGuardarInput;errors:CatalogoSistemaFieldErrors;disabled?:boolean}>();const emit=defineEmits<{updateDraft:[draft:CatalogoSistemaGuardarInput];blurName:[]}>();const length=computed(()=>props.draft.nombre.length);function updateName(e:Event){emit("updateDraft",{...props.draft,nombre:(e.target as HTMLInputElement).value})}function updateActive(activo:boolean){emit("updateDraft",{...props.draft,activo})}</script>
<template><form class="space-y-5" @submit.prevent><div><label for="sistema-name" class="mb-1.5 block text-xs font-semibold text-gray-800">Nombre para mostrar <span class="text-danger">*</span></label><input id="sistema-name" :value="draft.nombre" type="text" required :maxlength="SISTEMA_NOMBRE_MAX+1" autocomplete="off" class="min-h-11 w-full rounded-md border bg-white px-3 text-base outline-none focus:ring-2 md:min-h-9 md:text-sm" :class="errors.nombre?'border-danger focus:ring-danger/15':'border-gray-300 focus:border-main focus:ring-main/15'" :disabled="disabled" :aria-invalid="Boolean(errors.nombre)" :aria-describedby="errors.nombre?'sistema-name-error sistema-name-count':'sistema-name-count'" @input="updateName" @blur="emit('blurName')"/><div class="mt-1 flex min-h-5 justify-between gap-2 text-xs"><p v-if="errors.nombre" id="sistema-name-error" class="text-danger" role="alert">{{ errors.nombre }}</p><span v-else/><span id="sistema-name-count" class="tabular-nums text-gray-500">{{ length }}/{{ SISTEMA_NOMBRE_MAX }}</span></div></div><fieldset :disabled="disabled"><legend class="mb-1.5 text-xs font-semibold text-gray-800">Estado</legend><div class="grid grid-cols-2 gap-2"><button v-for="option in [{label:'Activo',value:true},{label:'Desactivado',value:false}]" :key="option.label" type="button" role="radio" :aria-checked="draft.activo===option.value" class="min-h-11 rounded-md border px-3 text-sm font-semibold md:min-h-9 md:text-xs" :class="[draft.activo===option.value?'border-main bg-main text-white':'border-gray-300 bg-white text-gray-600 hover:bg-gray-50',disabled?'cursor-not-allowed opacity-60':'cursor-pointer']" @click="updateActive(option.value)">{{ option.label }}</button></div><p class="mt-2 text-xs text-gray-500">Desactivar el sistema conserva todas sus asociaciones.</p></fieldset></form></template>
